"""Guard against the failure that has now happened twice: editing a generated file.

docs/PROGRAMME.md and docs/NITROGEN.md are both written by scripts. Both were, at some
point, improved by editing the *output* instead of the generator - and both would have
been silently reverted the next time the generator ran. NITROGEN.md actually was: one
run deleted 278 lines, and only a diff against git got them back.

The rule this enforces is deliberately weak, because a strong one cannot run here: a
full check would regenerate every document and compare, and regeneration needs the raw
data, which is gitignored. So the weak rule is the pairing one - **if a generated file
is committed as changed, its generator should be in the same commit.** That catches the
edit-the-output mistake without needing the data.

  python3 scripts/check_generated.py            what is generated by what
  python3 scripts/check_generated.py --staged   the pre-commit check
  python3 scripts/check_generated.py --audit    every past commit, worst first
  python3 scripts/check_generated.py --lost     candidates for eaten content
  python3 scripts/check_generated.py --regen    run every generator and diff — the
                                                only check that cannot be fooled

Install the hook with:  git config core.hooksPath .githooks
"""
import os
import re
import subprocess
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SCRIPTS = os.path.join(ROOT, "scripts")

# Paths a script writes into docs/. Both spellings are in use in this repo: the
# os.path.join form and the plain string.
JOIN = re.compile(r'os\.path\.join\(\s*ROOT\s*,\s*"docs"\s*(?:,\s*"([^"]+)")+\s*\)')
JOIN_PARTS = re.compile(r'"([^"]+)"')
PLAIN = re.compile(r'"(docs/[A-Za-z0-9_./-]+\.(?:md|html|svg|json|png))"')


def generated_map():
    """{docs/path: [scripts that write it]} - read out of the scripts themselves.

    Derived rather than declared, so a new generator is covered the day it is written
    and nobody has to remember to add it to a list.
    """
    out = {}
    for fn in sorted(os.listdir(SCRIPTS)):
        if not fn.endswith(".py"):
            continue
        src = open(os.path.join(SCRIPTS, fn), encoding="utf-8").read()
        paths = set()
        for m in JOIN.finditer(src):
            parts = JOIN_PARTS.findall(m.group(0))
            parts = [p for p in parts if p != "docs"]
            if parts:
                paths.add("docs/" + "/".join(parts))
        for m in PLAIN.finditer(src):
            paths.add(m.group(1))
        for p in paths:
            out.setdefault(p, []).append("scripts/" + fn)
    return out


def git(*args):
    return subprocess.run(["git", "-C", ROOT] + list(args),
                          capture_output=True, text=True).stdout.strip()


def check(files, gen):
    """Files that are generated, whose generator is not in the same set."""
    bad = []
    for f in files:
        if f in gen and not any(g in files for g in gen[f]):
            bad.append((f, gen[f]))
    return bad


def classify(before, after):
    """Split a regeneration diff into prose that would be LOST and numbers that
    are merely STALE.

    These are not the same thing and conflating them cost this project two days
    of wrong figures. The old version counted every removed line over 46
    characters as something regeneration "would remove", which is what a line
    reads like when only its digits changed - so a routine "the inputs moved,
    rerun me" was reported in the same words as "you are about to destroy
    hand-written prose". The safe-looking response to both is not to regenerate,
    and that is exactly the wrong response to the first: docs/FLOOD_GAP.md sat
    for two days quoting 5.932 km2 of modelled flooding when the Noerrebro sheet
    had been re-registered underneath it and the true figure was 5.847, along
    with a proximity headline that had moved by more than two points.

    A removed line counts as merely stale when the regenerated text contains a
    line identical to it once every run of digits is blanked. Anything else is
    prose with no replacement, and must be ported into the generator before
    regenerating - which is the rule the rest of this file exists to enforce."""
    import difflib
    import re
    d = list(difflib.unified_diff(before.split("\n"), after.split("\n"),
                                  n=0, lineterm=""))
    def skeleton(line):
        return re.sub(r"[0-9][0-9.,]*", "#", line[1:])
    removed = [l for l in d if l.startswith("-") and not l.startswith("---")
               and len(l) > 46]
    added = {skeleton(l) for l in d
             if l.startswith("+") and not l.startswith("+++")}
    lost, changed = [], []
    for l in removed:
        (changed if skeleton(l) in added else lost).append(l)
    return lost, changed


def main():
    gen = generated_map()
    arg = sys.argv[1] if len(sys.argv) > 1 else ""

    if arg == "--staged":
        files = set(git("diff", "--cached", "--name-only").split("\n")) - {""}
        bad = check(files, gen)
        for f, by in bad:
            print(f"  {f} is written by {', '.join(by)}, which is not in this commit",
                  file=sys.stderr)
        if bad:
            print("\nEither stage the generator too, or - if the change really is "
                  "only in the output - know that the next run will delete it.\n"
                  "Override with: git commit --no-verify", file=sys.stderr)
            return 1
        return 0

    if arg == "--audit":
        # Every commit that touched a generated file without its generator. This is
        # the archaeology: it finds the landmines already in the tree.
        hits = []
        for f, by in sorted(gen.items()):
            if not os.path.exists(os.path.join(ROOT, f)):
                continue
            log = git("log", "--format=%H %s", "--name-only", "--", f)
            commits = []
            cur = None
            for line in log.split("\n"):
                if not line.strip():
                    continue
                if re.match(r"^[0-9a-f]{40} ", line):
                    cur = line.split(" ", 1)
                    commits.append((cur[0], cur[1], []))
                elif commits:
                    commits[-1][2].append(line.strip())
            for sha, subject, touched in commits:
                # `git log -- <file>` lists only that path, so ask the commit itself
                all_touched = set(git("show", "--format=", "--name-only", sha)
                                  .split("\n")) - {""}
                if not any(g in all_touched for g in by):
                    hits.append((f, sha[:9], subject[:64]))
        by_file = {}
        for f, sha, subject in hits:
            by_file.setdefault(f, []).append((sha, subject))
        for f in sorted(by_file, key=lambda k: -len(by_file[k])):
            print(f"{f}  —  {len(by_file[f])} commit(s) without "
                  f"{', '.join(gen[f])}")
            for sha, subject in by_file[f][:4]:
                print(f"    {sha}  {subject}")
        if not hits:
            print("no generated file has ever been committed without its generator")
        return 0

    if arg == "--lost":
        # The real question is not whether the pairing rule was followed, it is
        # whether anything was actually lost. So: find every commit that changed a
        # generated file without touching its generator, take the lines it ADDED,
        # and ask whether those lines are still in the file today. A line that was
        # written by hand into an output and is now gone is content a regeneration
        # ate - and the commit that added it is where to get it back.
        TRIVIAL = re.compile(r"^[-|>*#\s]*$|^\|[-: |]+\|$")
        total = 0
        for f, by in sorted(gen.items()):
            if not f.endswith((".md", ".html")) or "*" in f:
                continue
            if not os.path.exists(os.path.join(ROOT, f)):
                continue
            here = set(l.strip() for l in
                       open(os.path.join(ROOT, f), encoding="utf-8"))
            shas = [x for x in git("log", "--format=%H", "--", f).split("\n") if x]
            for sha in shas:
                touched = set(git("show", "--format=", "--name-only", sha)
                              .split("\n")) - {""}
                if any(g in touched for g in by):
                    continue                      # generator moved with it: fine
                # Order matters and is easy to get backwards: the revision comes
                # before the "--", the path after it. Reversed, git reads the sha as
                # a pathspec, returns nothing, and the check passes everything.
                diff = git("show", "--format=", "--unified=0", sha, "--", f)
                added = [l[1:].strip() for l in diff.split("\n")
                         if l.startswith("+") and not l.startswith("+++")]
                gone = [l for l in added
                        if len(l) > 45 and not TRIVIAL.match(l) and l not in here]
                if not gone:
                    continue
                # A line can be missing for two very different reasons, and only one
                # of them is a loss. Ask which commit removed it: if that commit
                # also changed the generator, somebody rewrote the passage on
                # purpose. If it changed only the output, a regeneration ate it.
                eaten = []
                for l in gone[:40]:
                    rm = [x for x in git("log", "--format=%H", "-S", l, "--", f)
                          .split("\n") if x]
                    if not rm:
                        continue
                    killer = rm[0]                      # newest commit touching it
                    if killer == sha:
                        continue
                    kt = set(git("show", "--format=", "--name-only", killer)
                             .split("\n")) - {""}
                    if not any(g in kt for g in by):
                        eaten.append((l, killer))
                if not eaten:
                    continue
                subject = git("show", "--format=%s", "-s", sha)
                print(f"\n{f}  added in {sha[:9]}  {subject[:60]}")
                print(f"  {len(eaten)} line(s) removed later by a commit that did "
                      f"NOT touch {', '.join(by)} — recover with:")
                print(f"    git show {sha[:9]}:{f}")
                for l, killer in eaten[:3]:
                    print(f"      removed in {killer[:9]} | {l[:96]}")
                total += len(eaten)
        print(f"\n{total} orphaned line(s) in total"
              if total else "\nnothing lost by that pathway")
        return 0

    if arg == "--regen":
        # The authoritative check, and the only one that cannot be fooled: run the
        # generator and diff. Anything the output has that the generator does not
        # produce shows up here as a deletion. It needs the raw data, so it runs
        # where the data is and not in CI - which is the whole reason the weaker
        # checks above exist at all.
        wanted = sys.argv[2:] or [f for f in sorted(gen)
                                  if f.endswith(".md") and "*" not in f
                                  and os.path.exists(os.path.join(ROOT, f))]
        bad, skipped = [], []
        for f in wanted:
            by = [g for g in gen.get(f, []) if "glossary" not in g]
            if not by:
                continue
            before = git("show", "HEAD:" + f)
            r = subprocess.run([sys.executable, by[0]], cwd=ROOT,
                               capture_output=True, text=True, timeout=1800)
            after_path = os.path.join(ROOT, f)
            after = open(after_path, encoding="utf-8").read().rstrip("\n")
            if r.returncode != 0:
                skipped.append((f, by[0], (r.stderr or "").strip().split("\n")[-1][:90]))
            elif after != before.rstrip("\n"):
                lost, changed = classify(before, after)
                bad.append((f, by[0], lost, changed))
            git("checkout", "--", f)
            print(("  ok      " if (f, by[0]) not in [(x[0], x[1]) for x in bad]
                   else "  DIFFERS ") + f)
        print()
        for f, g, lost, changed in bad:
            if changed and not lost:
                print(f"{f}: STALE. {len(changed)} line(s) differ only in their "
                      f"numbers - regenerate with {g}.")
            elif lost and changed:
                print(f"{f}: {len(lost)} line(s) would be LOST and {len(changed)} "
                      f"are only stale numbers. Port the lost prose into {g} "
                      f"first, then regenerate.")
            else:
                print(f"{f}: {len(lost)} line(s) would be LOST. Port them into "
                      f"{g} before regenerating.")
            for l in lost[:2]:
                print(f"    LOST    {l[1:100]}")
            for l in changed[:2]:
                print(f"    stale   {l[1:100]}")
        for f, g, err in skipped:
            print(f"{f}: {g} did not run here — {err}")
        if not bad:
            print("every generator reproduces its own output" if not skipped
                  else "every generator that could run reproduces its own output")
        return 1 if bad else 0

    for f in sorted(gen):
        print(f"{f:44} <- {', '.join(gen[f])}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
